/// Выполняет асинхронное действие с повторными попытками при возникновении ошибок HTTP.
/// Использует экспоненциальную задержку между попытками для снижения нагрузки на сервер.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая целое число, которую нужно выполнить.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат выполнения действия (целое число).</returns>
/// <exception cref="InvalidOperationException">Возникает, если все попытки исчерпаны и действие не удалось выполнить.</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения действия с заданным количеством попыток
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить действие и вернуть его результат
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Если произошла ошибка HTTP и это не последняя попытка:
            // Вычисляем экспоненциальную задержку: 200мс * 2^i
