/**
 * Функция debounce (дебаунс) для отложенного выполнения функции.
 *
 * @param fn - Функция, которую нужно выполнить с задержкой.
 *             Тип T расширяет функцию, принимающую любые аргументы и возвращающую void.
 * @param ms - Время задержки в миллисекундах.
 * @returns Возвращает новую функцию, которая при вызове откладывает выполнение fn
 *          на ms миллисекунд. Если функция вызывается повторно до истечения задержки,
 *          предыдущий таймер отменяется, и задержка начинается заново.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Тип ReturnType<typeof setTimeout> гарантирует корректный тип для clearTimeout.
  // Начальное значение undefined, так как таймер еще не создан.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная fn.
  // Parameters<T> извлекает тип аргументов из типа функции T.
  return (...args: Parameters<T>) => {
    // Если таймер уже существует (t не undefined), отменяем его.
    // Это обеспечивает "дебаунс" эффект: только последний вызов будет выполнен.
    if (t) clearTimeout(t);

    // Создаем новый таймер, который через ms миллисекунд вызовет fn
    // с переданными аргументами args.
    // Сохраняем идентификатор таймера в переменную t для возможной отмены.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

