/**
 * Безопасно получает значение по ключу из карты.
 * Если значения нет, вызывает фабричную функцию для создания нового значения,
 * сохраняет его в карту и возвращает.
 *
 * @param K Тип ключа
 * @param V Тип значения
 * @param key Ключ, по которому ищется значение
 * @param factory Функция, создающая новое значение, если его нет в карте
 * @return Значение, найденное в карте или созданное фабрикой
 */
fun <K, V> MutableMap<K, V>.getOrPutSafe(key: K, factory: () -> V): V =
    // Обеспечивает потокобезопасность, блокируя доступ к карте на время выполнения блока
    synchronized(this) {
        // Пытается получить значение по ключу. Если значение отсутствует, выражение возвращает null
        this[key]
        // Если значение отсутствует (null), вызывает фабричную функцию для создания нового значения
        ?: factory()
        // Сохраняет созданное значение в карту под указанным ключом и возвращает его
        .also { this[key] = it }
    }
